import java.util.*;

/** A tree node: a name, a value and an ordered list of children. */
class Node {
    String name;
    int value;
    List<Node> children = new ArrayList<>();

    Node(String name, int value) {
        this.name = name;
        this.value = value;
    }
}

class Solution {
    public Node merge(Node t1, Node t2) {

        return null;
    }

    // ---- Provided: converts the JSON trees to Node and back. Keep this. ----
    public Map<String, Object> mergeTrees(Map<String, Object> t1, Map<String, Object> t2) {
        return toMap(merge(toNode(t1), toNode(t2)));
    }

    @SuppressWarnings("unchecked")
    private static Node toNode(Map<String, Object> m) {
        Node node = new Node((String) m.get("name"), ((Number) m.get("value")).intValue());
        for (Object child : (List<Object>) m.get("children")) node.children.add(toNode((Map<String, Object>) child));
        return node;
    }

    private static Map<String, Object> toMap(Node node) {
        if (node == null) return null;
        Map<String, Object> m = new LinkedHashMap<>();
        m.put("name", node.name);
        m.put("value", node.value);
        List<Object> children = new ArrayList<>();
        for (Node child : node.children) children.add(toMap(child));
        m.put("children", children);
        return m;
    }
}
